For $x, q \in \mathbb{C}$ with $0 < |q| < |x| < 1$, one has (as noted, for instance, in [tannery1898elements])
\begin{equation} 
    \frac{(q; q)^2}{\left\langle x; q \right\rangle} 
    =
    \sum_{m, n \geq 0} \left( q^{(2m+1)n} - q^{(2n+1)(m+1)}\right) x^{m-n},
\end{equation}
Moreover, one has
\begin{equation} 
    \frac{(q; q)^4}{\left\langle x; q\right\rangle^2}
    =
    \sum_{m, n \geq 0} \left(m+n+1\right) q^{(m+1)n} x^{m-n}.
\end{equation}
If additionally $y \in \mathbb{C}$ such that $|q| < |y| < 1$, then as noted by Hickerson [hickerson1988proof],
\begin{equation} 
   (q; q)^2 \frac{ \left\langle xy; q \right\rangle}{\left\langle x; q \right\rangle \left\langle y; q \right\rangle} = 
    \sum_{m, n \ge 0} q^{mn} x^m y^n - \sum_{m, n \ge 1} q^{mn} x^{-m} y^{-n}.
\end{equation}

Let $0 \neq \alpha \in \mathbb{C}$, $s \in \{\pm 1\}$ and $d, k, a \in \mathbb{Z}$ with $0 \le k \le d-1$ and $1 \le a \mid d$. If $sa = d$ assume that $|y| < \left\vert \alpha q^k \right\vert$, and if $sa = -d$ assume that $|y| < \left\vert q^{d-k}/\alpha\right\vert$. Then
\begin{equation}
    \underbrace{\sum_{n \in \mathbb{Z}} \alpha^n q^{d\binom{n}{2}+kn} x^{dn+k}}_{\text{Original series $\big[{\alpha x^d};{k}\big]$}} \underbrace{\vphantom{\sum_{n \in \mathbb{Z}}} \left(q^{san}x^{sa} y; q^{a}\right)}_{\text{Twist factor}}
    =
    \sum_{\ell=0}^{d-1} W_{k,\ell}(y, q)
    \big[{\alpha x^d};{\ell}\big],
\end{equation}
where $\{W_{k,\ell}(y, q)\}_\ell$ also depend on $\alpha, s, d, a$ (but not on $x$), and are given by
\begin{equation}
    W_{k,\ell}(y, q)
    = 
    \mathbbm{1}_{\ell \equiv k\ (\textnormal{mod }a)} \cdot
    q^{a \binom{j}{2}}
    \sum_{n \ge \mathbbm{1}_{s\ell < sk}}
    \alpha^{-sn}\ \frac{q^{a \binom{b}{2} n^2 + s(b(\ell-k)-\ell)n + \frac{s-1}{2}dn}}{\left(q^{a}; q^{a}\right)_{bn+j}} (-y)^{bn+j},
\end{equation}
where $b := d/a$ and $j := (\ell - k)/(sa)$.

\begin{align}
    (q; q)\left\langle x; q \right\rangle \left\langle qx^2; q^2 \right\rangle &=  
    \big[{qx^3};{0}\big] - \big[{qx^3};{1}\big]
    , \\[4pt]
    (q; q) \left\langle x; q \right\rangle \left\langle qx^2; q^2 \right\rangle \left\langle x^2; q^2 \right\rangle &= - \frac{\big[{-qx^5};{1}\big] + \big[{-qx^5};{2}\big]}{\left\langle q^2; q^5 \right\rangle} + \frac{\big[{-qx^5};{0}\big] + \big[{-qx^5};{3}\big]}{\left\langle q; q^5 \right\rangle}. 

\end{align}

In $\mathcal{T}_{\mathbb{H}^{\textnormal{+}\hspace{-0.03cm}}}(1, qx)$, one has (see [hardy1979introduction] and [rogers1893second])
\begin{equation} 
\begin{aligned}
    \sum_{n \geq 0} \frac{q^{n^2}}{(q; q)_n} x^n 
    &= 
    \sum_{n \geq 0}(-1)^n \frac{q^{5\binom{n}{2}+2n}}{(q; q)_n \left(q^n x; q\right)} \left(1 - q^{2n} x\right) x^{2n}
    \\
    &=
    \sum_{n \ge 0} 
    \frac{q^{n^2}}{\left(q^2; q^2\right)_n} x^n \left(-q^{2n+2} x; q^2\right).
\end{aligned}
\end{equation}
In fact, the left-hand side lies in $\mathcal{T}_{\mathbb{C}}(1, qx)$, and thus all the singularities on the right are removable.

In $\mathcal{T}_{\mathbb{C}}\left(-qx^4\right) \cap \mathcal{S}_{\mathbb{C}}\left(x^2\right)$, one has
\begin{equation}
\begin{aligned}
    (q; q)\left(q; q^2\right) \left\langle x; q \right\rangle^2 \left\langle qx^2; q^2 \right\rangle &= 
    \hspace{0.19cm} \left(-q; q^2\right)\left(\big[{-qx^4};{0}\big] + \big[{-qx^4};{2}\big]\right) \\
    &- 2\left(-q^2; q^2\right) \big[{-qx^4};{1}\big].
\end{aligned}
\end{equation}

As an identity of functions in $\mathcal{T}_{\mathbb{C}}\left(q^2x^7\right)$,
\begin{equation} 
\begin{split}
    (q;q) \left\langle x; q \right\rangle \left\langle qx^2; q^2 \right\rangle^2 \left\langle x^2; q^2 \right\rangle
    &=
    - \frac{\big[{q^2x^7};{1}\big] + \big[{q^2x^7};{2}\big]}{\left\langle q^2 ; q^7 \right\rangle^2 \left\langle q; q^7\right\rangle}
    +
    \frac{\big[{q^2x^7};{0}\big] + \big[{q^2x^7};{3}\big]}{\left\langle q ; q^7 \right\rangle^2 \left\langle q^3; q^7\right\rangle}
    \\[4pt]
    &
    + 
    q\frac{\big[{q^2x^7};{-1}\big] + \big[{q^2x^7};{4}\big]}{\left\langle q^3 ; q^7 \right\rangle^2 \left\langle q^2; q^7\right\rangle} 
    - 
    q\frac{2\big[{q^2x^7};{5}\big]}{\left\langle q; q^7\right\rangle \left\langle q^2; q^7 \right\rangle \left\langle q^3; q^7 \right\rangle }.
\end{split}
\end{equation}

In $\mathcal{T}_{\mathbb{C}}\left(-q^5 x^{13}\right) \cap \mathcal{S}_{\mathbb{C}}\left(x^3\right)$, one has
\begin{equation} 
\begin{aligned}
    (q; q)\left\langle x; q \right\rangle \left\langle qx^2; q^2 \right\rangle \left\langle x^2; q^2 \right\rangle &\left\langle qx^4; q^2 \right\rangle
    \\
    =
    -&\frac{\big[{-q^5x^{13}};{1}\big] + \big[{-q^5x^{13}};{2}\big]}{\left\langle q^3,q^4,q^5,q^6 ; q^{13}\right\rangle \left\langle q^2 ; q^{26} \right\rangle}
    +
    \frac{\big[{-q^5x^{13}};{0}\big] + \big[{-q^5x^{13}};{3}\big]}{\left\langle q,q^2,q^4,q^5 ; q^{13}\right\rangle \left\langle q^6 ; q^{26} \right\rangle}
    \\[7pt]
    -\ q&\frac{\big[{-q^5x^{13}};{-1}\big] + \big[{-q^5x^{13}};{4}\big]}{\left\langle q,q^2,q^4,q^6 ; q^{13}\right\rangle \left\langle q^{10} ; q^{26} \right\rangle}
    -q^2
    \frac{\big[{-q^5x^{13}};{-2}\big] + \big[{-q^5x^{13}};{5}\big]}{\left\langle q^2,q^3,q^4,q^5 ; q^{13}\right\rangle \left\langle q^{14} ; q^{26} \right\rangle}
    \\[7pt]
    +\ q&\frac{\big[{-q^5x^{13}};{-3}\big] + \big[{-q^5x^{13}};{6}\big]}{\left\langle q,q^2,q^3,q^4 ; q^{13}\right\rangle \left\langle q^{18} ; q^{26} \right\rangle}
    -q
    \frac{\big[{-q^5x^{13}};{-4}\big] + \big[{-q^5x^{13}};{7}\big]}{\left\langle q,q^3,q^5,q^6 ; q^{13}\right\rangle \left\langle q^{22} ; q^{26} \right\rangle},
\end{aligned}
\end{equation}
where we used the common notation $\left\langle q^{a_1}, q^{a_2}, \ldots, q^{a_k}; q^b \right\rangle := \prod_{j=1}^k \left\langle q^{a_j}; q^b \right\rangle$.

In $\mathcal{T}_{\mathbb{H}^{\textnormal{-}\hspace{-0.03cm}}}\left(qx^2-x\right)$, one has 
\begin{equation}
    (q; q) \left\langle x; q \right\rangle (qx; q)\ =  
    \sum_{m \in \mathbb{Z}, n \ge 0} \frac{q^{\binom{m}{2} + \binom{n+1}{2}}}{(q; q)_n} (-x)^{m+n}
    \ =\ 
    \frac{\big[{qx^2 - x};{0}\big]}{\left\langle q^2; q^5 \right\rangle} - \frac{\big[{qx^2 - x};{1}\big]}{\left\langle q; q^5 \right\rangle},
\end{equation}
where for $k \in \{0, 1\}$, $\big[{qx^2 - x};{k}\big]$ is the unique function in $\mathcal{T}_{\mathbb{H}^{\textnormal{-}\hspace{-0.03cm}}}\left(qx^2-x\right)$ whose Fourier expansion in $z \in {\mathbb{H}}^-$ has coefficient of $x^j$ equal to $\mathbbm{1}_{j = k}$, for $j \in \{0, 1\}$.

