    \big[{qx^2};{0}\big] \vspace{0.1cm} \\
    \big[{qx^2};{1}\big]
    \end{pmatrix},
\]
where 
\begin{equation} 
    \begin{pmatrix}
    A(q) & B(q) \vspace{0.1cm}\\
    C(q) & D(q)
    \end{pmatrix}
    =
    \frac{\left(q^{10}; q^{10}\right)}{(q; q)}
    \begin{pmatrix}
